@php($x=$historicalPunishment ?? null)
<div class="row g-3">@foreach(['bcs'=>'BCS','reg'=>'REG','name'=>'Name','fname'=>'Father Name','mname'=>'Mother Name','b_date'=>'Birth Date','dob'=>'DOB (secondary)','dist_name'=>'District','ssc_roll'=>'SSC Roll','ssc_year'=>'SSC Year','hsc_roll'=>'HSC Roll','hsc_year'=>'HSC Year','nid_no'=>'NID'] as $n=>$l)<div class="col-md-6"><label class="form-label">{{$l}}</label><input class="form-control" name="{{$n}}" type="{{in_array($n,['b_date','dob'])?'date':'text'}}" value="{{old($n, $x?->{$n} instanceof \Carbon\CarbonInterface ? $x->{$n}->format('Y-m-d') : $x?->{$n})}}"></div>@endforeach</div>
<label class="form-check mt-3"><input id="life" class="form-check-input" type="checkbox" name="is_lifetime" value="1" @checked(old('is_lifetime',$x?->is_lifetime))><span class="form-check-label">Lifetime punishment</span></label><div class="row g-3 mt-1"><div class="col-md-6"><label class="form-label">Punishment Start</label><input id="pstart" type="date" class="form-control" name="punishment_start" value="{{old('punishment_start',$x?->punishment_start?->format('Y-m-d'))}}"></div><div class="col-md-6"><label class="form-label">Punishment End</label><input id="pend" type="date" class="form-control" name="punishment_end" value="{{old('punishment_end',$x?->punishment_end?->format('Y-m-d'))}}"></div></div><label class="form-label mt-3">Reason (optional)</label><textarea class="form-control" rows="4" name="punishment_reason">{{old('punishment_reason',$x?->punishment_reason)}}</textarea>
@push('scripts')<script>function lifeDates(){const e=document.getElementById('life'),on=e&&e.checked;['pstart','pend'].forEach(id=>{const x=document.getElementById(id);if(!x)return;x.disabled=on;if(on)x.value='';});}document.addEventListener('DOMContentLoaded',()=>{document.getElementById('life')?.addEventListener('change',lifeDates);lifeDates();});</script>@endpush
